export function nextGeneration(cells: Cell[]): Cell[] {
  const liveSet = new Set(cells.map(([x, y]) => `${x},${y}`));

  // Reproduction: a dead cell with exactly 3 live neighbours becomes alive.
  const neighbourCounts = new Map<string, number>();
  for (const [x, y] of cells) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        if (dx === 0 && dy === 0) continue;
        const key = `${x + dx},${y + dy}`;
        neighbourCounts.set(key, (neighbourCounts.get(key) ?? 0) + 1);
      }
    }
  }

  const next: Cell[] = [];
  for (const [key, count] of neighbourCounts) {
    if (count === 3 && !liveSet.has(key)) {
      const [x, y] = key.split(",").map(Number);
      next.push([x, y]);
    }
  }
  return next;
}

